interface LogoProps {
  className?: string;
  size?: number | string;
  showText?: boolean;
  textColor?: string;
  subTextColor?: string;
  variant?: 'full' | 'mark';
}

/**
 * VietTrack Signature Logo
 * - Bản đồ Việt Nam chuẩn xác 100% nguyên bản (Flag_map_of_Vietnam.svg)
 * - Bản đồ được căn chỉnh vào CHÍNH GIỮA đĩa tròn
 * - Location Pin Hà Nội Sao Vàng phóng to ấn tượng, vươn cao vượt ra ngoài viền tròn
 * - Cung đường hành trình du lịch uốn lượn NẰM 100% TRÊN THÂN BẢN ĐỒ
 * - Pin TP.HCM Phương Nam ấm áp nằm chuẩn xác trên vùng đất Nam Bộ
 */
export const VietTrackLogoMark: React.FC<{ size?: number | string; className?: string }> = ({
  size = 48,
  className = '',
}) => {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 240 240"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={`shrink-0 select-none overflow-visible ${className}`}
      aria-label="Đi Du Lịch Logo"
    >
      <defs>
        {/* Nền đĩa ngọc trắng sương mai dịu mát */}
        <radialGradient id="vjBgPlate" cx="30%" cy="25%" r="75%">
          <stop offset="0%" stopColor="#FFFFFF" />
          <stop offset="65%" stopColor="#F6FAF8" />
          <stop offset="100%" stopColor="#E6F2ED" />
        </radialGradient>

        {/* Viền đĩa tròn tinh tế (Vàng Sun & Deep Teal) */}
        <linearGradient id="vjBorderGrad" x1="20" y1="20" x2="220" y2="220" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#F59E0B" stopOpacity="0.8" />
          <stop offset="50%" stopColor="#06B6D4" stopOpacity="0.5" />
          <stop offset="100%" stopColor="#048C73" stopOpacity="0.9" />
        </linearGradient>

        {/* Gradient xanh sinh thái thiên nhiên cho bản đồ Việt Nam */}
        <linearGradient id="vjGreenMapGrad" x1="90" y1="35" x2="130" y2="200" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#10B981" />
          <stop offset="35%" stopColor="#059669" />
          <stop offset="75%" stopColor="#048C73" />
          <stop offset="100%" stopColor="#025A4A" />
        </linearGradient>

        {/* Soft Shadow cho khối bản đồ */}
        <filter id="vjMapShadow" x="60" y="25" width="165" height="195" filterUnits="userSpaceOnUse">
          <feDropShadow dx="1.5" dy="3.5" stdDeviation="3" floodColor="#048C73" floodOpacity="0.28" />
        </filter>

        {/* Pin Hà Nội (Đỏ cờ sao vàng) */}
        <linearGradient id="vjNorthPinGrad" x1="80" y1="2" x2="120" y2="62" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#EF4444" />
          <stop offset="100%" stopColor="#B91C1C" />
        </linearGradient>
        <filter id="vjBigPinGlow" x="60" y="-8" width="80" height="85" filterUnits="userSpaceOnUse">
          <feDropShadow dx="0" dy="4" stdDeviation="3.5" floodColor="#7F1D1D" floodOpacity="0.45" />
        </filter>

        {/* Pin TP.HCM Phương Nam (Cam San Hô CTA) */}
        <linearGradient id="vjSouthPinGrad" x1="118" y1="152" x2="130" y2="174" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#F97316" />
          <stop offset="100%" stopColor="#EA580C" />
        </linearGradient>
        <filter id="vjSouthGlow" x="110" y="148" width="30" height="36" filterUnits="userSpaceOnUse">
          <feDropShadow dx="0" dy="2" stdDeviation="1.8" floodColor="#9A3412" floodOpacity="0.35" />
        </filter>

        {/* Sao vàng rực rỡ */}
        <linearGradient id="vjBigStarGrad" x1="94" y1="16" x2="106" y2="40" gradientUnits="userSpaceOnUse">
          <stop offset="0%" stopColor="#FFF59D" />
          <stop offset="50%" stopColor="#FDE047" />
          <stop offset="100%" stopColor="#F59E0B" />
        </linearGradient>
      </defs>

      {/* 1. KHUNG ĐĨA TRÒN VIỀN KIM - NGỌC (Bán kính chuẩn, bản đồ nằm cân đối ở giữa) */}
      <circle cx="120" cy="120" r="105" fill="url(#vjBgPlate)" />
      <circle cx="120" cy="120" r="103" stroke="url(#vjBorderGrad)" strokeWidth="2.5" />
      <circle cx="120" cy="120" r="98" stroke="#048C73" strokeWidth="0.8" strokeOpacity="0.16" strokeDasharray="3.5 4" />

      {/* 2. BẢN ĐỒ VIỆT NAM CHUẨN XÁC 100% CĂN VÀO CHÍNH GIỮA ĐĨA TRÒN */}
      <g filter="url(#vjMapShadow)">
        <path
          d={VIETNAM_MAP_PATH}
          transform="matrix(0.036145 0 0 0.036145 45.825 82.77)"
          fill="url(#vjGreenMapGrad)"
          stroke="#036A57"
          strokeWidth="1.5"
          strokeLinejoin="round"
        />
      </g>

      {/* 3. CUNG ĐƯỜNG HÀNH TRÌNH DU LỊCH — NẰM CHÍNH TÂM 100% TRÊN THÂN BẢN ĐỒ */}
      <path
        d="
          M 100 56
          C 103 72, 102 82, 108 90
          C 113 96, 118 103, 124 110
          C 132 118, 137 128, 138.5 142
          C 139.5 152, 136 160, 124 168
        "
        stroke="#0F172A"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeDasharray="2.8 3.8"
        opacity="0.95"
      />

      {/* 4. LOCATION PIN PHƯƠNG NAM (TP. HỒ CHÍ MINH) — CHÓP CẮM TẠI (124, 168) NẰM TRỌN TRÊN BẢN ĐỒ */}
      <g filter="url(#vjSouthGlow)">
        <path
          d="
            M 124 153
            C 120.5 153, 117.5 156, 117.5 159.5
            C 117.5 164, 124 169.5, 124 169.5
            C 124 169.5, 130.5 164, 130.5 159.5
            C 130.5 156, 127.5 153, 124 153
            Z
          "
          fill="url(#vjSouthPinGrad)"
        />
        <circle cx="124" cy="159.5" r="2.2" fill="#FFFFFF" />
      </g>

      {/* 5. LOCATION PIN MIỀN BẮC SAO VÀNG — TO LỚN NỔI BẬT, VƯỢT QUÁ KHUNG TRÒN */}
      <g filter="url(#vjBigPinGlow)">
        {/* Thân Pin Đỏ rực rỡ, to cao vươn khỏi viền tròn đĩa */}
        <path
          d="
            M 100 2
            C 84 2, 72 14, 72 30
            C 72 44, 100 62, 100 62
            C 100 62, 128 44, 128 30
            C 128 14, 116 2, 100 2
            Z
          "
          fill="url(#vjNorthPinGrad)"
          stroke="#FFFFFF"
          strokeWidth="1.6"
        />
        {/* Vòng hào quang sao vàng */}
        <circle cx="100" cy="28" r="15" fill="#FFFFFF" fillOpacity="0.28" />

        {/* Ngôi sao vàng 5 cánh to lớn, sắc sảo */}
        <path
          d="
            M 100 16
            L 103.5 25
            L 113 25.5
            L 105.5 31.5
            L 108.5 40.5
            L 100 35
            L 91.5 40.5
            L 94.5 31.5
            L 87 25.5
            L 96.5 25
            Z
          "
          fill="url(#vjBigStarGrad)"
          stroke="#F59E0B"
          strokeWidth="0.8"
        />
      </g>
    </svg>
  );
};

export const VietTrackLogo: React.FC<LogoProps> = ({
  size = 54,
  className = '',
  showText = true,
  textColor = 'text-[#0f2d3c]',
  subTextColor = 'text-[#66716c]',
  variant = 'full',
}) => {
  if (variant === 'mark' || !showText) {
    return <VietTrackLogoMark size={size} className={className} />;
  }

  return (
    <div className={`inline-flex items-center gap-3 sm:gap-3.5 ${className}`}>
      <VietTrackLogoMark size={size} />
      <div className="flex flex-col select-none leading-tight">
        <span 
          className={`font-bold text-2xl sm:text-[27px] tracking-normal ${textColor}`}
          style={{ fontFamily: "'Outfit', 'Be Vietnam Pro', sans-serif" }}
        >
          Đi Du Lịch
        </span>
        <span 
          className={`text-[10px] sm:text-[11px] font-medium tracking-[0.14em] uppercase mt-0.5 ${subTextColor}`}
          style={{ fontFamily: "'Be Vietnam Pro', sans-serif" }}
        >
          Du Lịch Di Sản &amp; Sinh Thái
        </span>
      </div>
    </div>
  );
};

// Aliases for compatibility
export const DiDuLichLogoMark = VietTrackLogoMark;
export const DiDuLichLogo = VietTrackLogo;
export const VietJourneyLogoMark = VietTrackLogoMark;
export const VietJourneyLogo = VietTrackLogo;

export default VietTrackLogo;

